import{at as e,it as t,n,vt as r}from"./chunks/framework.BZu6EPoN.js";var i=JSON.parse(`{"title":"物理核和vCPU的关系","description":"","frontmatter":{"title":"物理核和vCPU的关系","date":"2025-09-24","summary":"物理CPU和vCPU的对应或分配关系，一个物理CPU能虚拟出多少个vCPU","tags":["硬件"],"draft":false,"authors":["default"]},"headers":[],"relativePath":"zh/blog/physical-cores-vcpus.md","filePath":"zh/blog/physical-cores-vcpus.md"}`),a={name:`zh/blog/physical-cores-vcpus.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h3 id="_1-cpu个数" tabindex="-1">1.CPU个数 <a class="header-anchor" href="#_1-cpu个数" aria-label="Permalink to “1.CPU个数”">​</a></h3><p>在购买物理服务器时，一般我们可以看到一台计算机的CPU数量，比如一颗或者两颗。</p><h3 id="_2-cpu物理核数" tabindex="-1">2.CPU物理核数 <a class="header-anchor" href="#_2-cpu物理核数" aria-label="Permalink to “2.CPU物理核数”">​</a></h3><p>每颗CPU有多个物理核数，例如24cores，48cores</p><h3 id="_3-pcpu" tabindex="-1">3.PCPU <a class="header-anchor" href="#_3-pcpu" aria-label="Permalink to “3.PCPU”">​</a></h3><p><strong>PCPU</strong> 是 “<strong>Physical CPU（物理中央处理器）</strong>” 的缩写，常用于虚拟化、云计算和操作系统等领域，用来指代实际存在于硬件中的处理器核心或线程资源。比如你有一个 Intel i7 的 CPU，它可能有 4 个物理核心，每个核心支持 2 个线程（超线程），那么你就有 4 个 PCPU，8 个 vCPU（虚拟 CPU）。</p><p><img src="https://markdownimage-1257263724.cos.ap-chengdu.myqcloud.com/typroa/download.jpeg" alt="img"></p><h3 id="_4-lcpu" tabindex="-1">4. LCPU <a class="header-anchor" href="#_4-lcpu" aria-label="Permalink to “4. LCPU”">​</a></h3><p>LCPU指的是CPU逻辑核数，通过超线程技术让一个物理核心模拟出的多个核心。<strong>LCPU数量 = PCPU数量 x 每个核心的线程数</strong>。</p><p><strong>超线程技术</strong> 允许一个物理核心同时处理两个线程，让操作系统“以为”有两个核心。这样，一个四核的CPU如果支持超线程，操作系统就会看到 4个PCPU * 2 = 8个LCPU。</p><h3 id="_5-vcpu" tabindex="-1">5. vCPU <a class="header-anchor" href="#_5-vcpu" aria-label="Permalink to “5. vCPU”">​</a></h3><p>一个逻辑核，在虚拟化环境中，分配给虚拟机的CPU资源。它最终由宿主机的PCPU执行。</p><h3 id="_6-超分比" tabindex="-1">6.超分比 <a class="header-anchor" href="#_6-超分比" aria-label="Permalink to “6.超分比”">​</a></h3><p>“<strong>超分比</strong>” 是一个常见于 <strong>虚拟化</strong> 和 <strong>云计算</strong> 场景的术语，通常指的是：</p><blockquote><p><strong>虚拟 CPU（vCPU）数量 与 物理 CPU（pCPU）数量 之间的比例</strong>，也叫 <strong>CPU overcommit ratio</strong>（CPU 超分配率）。</p></blockquote><hr><h3 id="🔧-详细解释" tabindex="-1">🔧 详细解释： <a class="header-anchor" href="#🔧-详细解释" aria-label="Permalink to “🔧 详细解释：”">​</a></h3><h4 id="✅-公式" tabindex="-1">✅ 公式： <a class="header-anchor" href="#✅-公式" aria-label="Permalink to “✅ 公式：”">​</a></h4><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>超分比 = vCPU 总数 ÷ pCPU 总数</span></span></code></pre></div><h4 id="✅-举例说明" tabindex="-1">✅ 举例说明： <a class="header-anchor" href="#✅-举例说明" aria-label="Permalink to “✅ 举例说明：”">​</a></h4><p>假设你有一台服务器，有：</p><ul><li>物理 CPU 核心（pCPU）：8 个</li><li>虚拟机总共使用了：32 个 vCPU</li></ul><p>那么：</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>超分比 = 32 vCPU ÷ 8 pCPU = 4</span></span></code></pre></div><p>这意味着：<strong>每个物理核心被“超卖”了 4 倍</strong>，或者说：<strong>4 个 vCPU 共享 1 个 pCPU</strong>。</p><hr><h3 id="🧠-为什么要超分" tabindex="-1">🧠 为什么要超分？ <a class="header-anchor" href="#🧠-为什么要超分" aria-label="Permalink to “🧠 为什么要超分？”">​</a></h3><p>在实际使用中，并不是所有虚拟机都会一直占满 CPU。很多业务负载是间歇性的（如 Web 服务、数据库查询等）。所以为了提升资源利用率，云平台会：</p><ul><li>分配比实际物理 CPU 更多的 vCPU</li><li>让多台虚拟机共享物理核心</li></ul><p>这种策略能大大提高 <strong>CPU 使用率和系统收益</strong>。</p><hr><h3 id="⚠️-超分比的影响" tabindex="-1">⚠️ 超分比的影响： <a class="header-anchor" href="#⚠️-超分比的影响" aria-label="Permalink to “⚠️ 超分比的影响：”">​</a></h3><table tabindex="0"><thead><tr><th>超分比</th><th>特点</th><th>风险</th></tr></thead><tbody><tr><td>较低（如 1:1 ~ 2:1）</td><td>性能好，资源浪费少</td><td>成本高</td></tr><tr><td>较高（如 4:1 ~ 8:1）</td><td>成本低，资源利用高</td><td>性能可能下降，争抢 CPU</td></tr></tbody></table><hr><h3 id="💡-最佳实践建议" tabindex="-1">💡 最佳实践建议： <a class="header-anchor" href="#💡-最佳实践建议" aria-label="Permalink to “💡 最佳实践建议：”">​</a></h3><ul><li><strong>数据库、视频转码、AI 推理等高负载场景</strong>：尽量不超分或超分低（如 1:1 ~ 2:1）。</li><li><strong>Web、办公、测试环境等轻负载场景</strong>：可以高超分（如 4:1 ~ 8:1，甚至更高）。</li><li>一些云服务商（如 AWS、阿里云）对不同实例类型设置了不同的超分比，但不公开详细比例。</li></ul><hr><h3 id="📝-总结一句话" tabindex="-1">📝 总结一句话： <a class="header-anchor" href="#📝-总结一句话" aria-label="Permalink to “📝 总结一句话：”">​</a></h3><blockquote><p><strong>超分比</strong> 是衡量 vCPU 和 pCPU 分配比例的指标，是虚拟化环境中提高资源利用率的常用策略，但需要在性能和性价比之间权衡。</p></blockquote><h3 id="_7-虚拟机vcpu的分配与调度" tabindex="-1">7. 虚拟机VCPU的分配与调度 <a class="header-anchor" href="#_7-虚拟机vcpu的分配与调度" aria-label="Permalink to “7. 虚拟机VCPU的分配与调度”">​</a></h3><p>对虚拟机来说，不直接感知物理CPU，虚拟机的计算单元通过vCPU对象来呈现。虚拟机只看到VMM呈现给它的vCPU。在VMM中，每个vCPU对应一个VMCS（Virtual-Machine Control Structure）结构，当VCPU被从物理CPU上切换下来的时候，其运行上下文会被保存在其对应的VMCS结构中；当VCPU被切换到PCPU上运行时，其运行上下文会从对应的VMCS结构中导入到物理CPU上。通过这种方式，实现各vCPU之间的独立运行。</p><p>从虚拟机系统的结构与功能划分可以看出，客户操作系统与虚拟机监视器共同构成了虚拟机系统的两级调度框架，如图所示是一个多核环境下虚拟机系统的两级调度框架。客户操作系统负责第2 级调度,即线程或进程在vCPU 上的调度（将核心线程映射到相应的VCPU上）。虚拟机监视器负责第1 级调度, 即vCPU在物理处理单元上的调度。两级调度的调度策略和机制不存在依赖关系。vCPU调度器负责物理处理器资源在各个虚拟机之间的分配与调度,本质上即把各个虚拟机中的vCPU按照一定的策略和机制调度在物理处理单元上可以采用任意的策略来分配物理资源, 满足虚拟机的不同需求。vCPU可以调度在一个或多个物理处理单元执行（分时复用或空间复用物理处理单元）, 也可以与物理处理单元建立一对一固定的映射关系（限制访问指定的物理处理单元）。</p><p><img src="https://markdownimage-1257263724.cos.ap-chengdu.myqcloud.com/typroa/download-20250924220315293.jpeg" alt="img"></p>`,43)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};